var densities = flow.get('lane_densities') || { 1: 5, 2: 3, 3: 8, 4: 4 };
var distances = flow.get('lane_distances') || { 1: 50, 2: 70, 3: 25, 4: 60 };
var systemMode = flow.get('system_mode') || 'SYNTHETIC';

var topic = msg.topic;
var payload = msg.payload;

// Match topic e.g. smart_traffic/demo/lane1/density
var match = topic.match(/lane(\d)\/density/);
if (match) {
    var laneId = parseInt(match[1]);
    var vCount = 0;
    var dist = 100;

    if (typeof payload === 'object') {
        vCount = payload.vehicle_count !== undefined ? payload.vehicle_count : 0;
        dist = payload.distance_cm !== undefined ? payload.distance_cm : 100;
    } else {
        vCount = parseInt(payload) || 0;
    }

    densities[laneId] = vCount;
    distances[laneId] = dist;
    flow.set('lane_densities', densities);
    flow.set('lane_distances', distances);

    // Output gauge updates to dashboard
    return [
        { topic: 'lane' + laneId, payload: vCount },
        { topic: 'lane' + laneId + '_dist', payload: dist }
    ];
}
return null;

var mode = 'SYNTHETIC';
if (typeof msg.payload === 'object' && msg.payload.mode) {
    mode = msg.payload.mode;
} else if (typeof msg.payload === 'string') {
    mode = msg.payload;
}
flow.set('system_mode', mode);
return { payload: mode };

var action = 'CLEAR';
var lane = 0;
if (typeof msg.payload === 'object') {
    action = msg.payload.action || 'CLEAR';
    lane = msg.payload.lane || 0;
}

if (action === 'OVERRIDE' && lane > 0) {
    flow.set('emergency_lane', lane);
    flow.set('emergency_active', true);
    node.warn('Emergency Vehicle Override: Lane ' + lane);
    return { payload: '🚨 ACTIVE (Lane ' + lane + ')' };
} else {
    flow.set('emergency_lane', 0);
    flow.set('emergency_active', false);
    return { payload: 'NORMAL (No Emergency)' };
}

// Adaptive Traffic Control Logic
var state = flow.get('traffic_state') || {
    active_lane: 1,
    phase: 'GREEN', // 'GREEN' or 'YELLOW'
    remaining_sec: 15,
    total_phase_sec: 15
};

var densities = flow.get('lane_densities') || { 1: 5, 2: 3, 3: 8, 4: 4 };
var emergencyActive = flow.get('emergency_active') || false;
var emergencyLane = flow.get('emergency_lane') || 0;
var systemMode = flow.get('system_mode') || 'SYNTHETIC';

// Calculate adaptive green time based on lane vehicle density
function calculateAdaptiveGreenTime(vehicles) {
    var BASE_TIME = 8;
    var TIME_PER_VEHICLE = 1.8;
    var MIN_GREEN = 6;
    var MAX_GREEN = 35;
    var calculated = Math.round(BASE_TIME + (vehicles * TIME_PER_VEHICLE));
    return Math.max(MIN_GREEN, Math.min(MAX_GREEN, calculated));
}

// 1. EMERGENCY OVERRIDE CHECK
if (emergencyActive && emergencyLane >= 1 && emergencyLane <= 4) {
    if (state.active_lane !== emergencyLane) {
        // Transition current lane to yellow before giving priority
        if (state.phase === 'GREEN') {
            state.phase = 'YELLOW';
            state.remaining_sec = 2;
            state.total_phase_sec = 2;
        } else if (state.phase === 'YELLOW' && state.remaining_sec <= 0) {
            state.active_lane = emergencyLane;
            state.phase = 'GREEN';
            state.remaining_sec = 25;
            state.total_phase_sec = 25;
        }
    } else {
        state.phase = 'GREEN';
        state.remaining_sec = Math.max(state.remaining_sec, 15);
    }
} else {
    // 2. NORMAL ADAPTIVE ROUND-ROBIN CYCLING
    state.remaining_sec -= 1;

    if (state.remaining_sec <= 0) {
        if (state.phase === 'GREEN') {
            // Transition to Yellow
            state.phase = 'YELLOW';
            state.remaining_sec = 3; // 3 seconds yellow buffer
            state.total_phase_sec = 3;
        } else {
            // Transition from Yellow to Next Lane Green
            state.active_lane = (state.active_lane % 4) + 1;
            var nextLaneVehicles = densities[state.active_lane] || 2;
            var allocatedGreen = calculateAdaptiveGreenTime(nextLaneVehicles);

            state.phase = 'GREEN';
            state.remaining_sec = allocatedGreen;
            state.total_phase_sec = allocatedGreen;
        }
    }
}

flow.set('traffic_state', state);

// Build light statuses for all 4 lanes
var lights = { 1: 'RED', 2: 'RED', 3: 'RED', 4: 'RED' };
lights[state.active_lane] = state.phase;

var fullPayload = {
    active_lane: state.active_lane,
    phase: state.phase,
    remaining_sec: state.remaining_sec,
    total_phase_sec: state.total_phase_sec,
    lane1: lights[1],
    lane2: lights[2],
    lane3: lights[3],
    lane4: lights[4],
    mode: systemMode,
    emergency_active: emergencyActive,
    emergency_lane: emergencyLane,
    timestamp: Date.now()
};

var outFull = { topic: 'smart_traffic/demo/control/lights', payload: fullPayload };
var outL1 = { topic: 'smart_traffic/demo/lane1/light', payload: lights[1] };
var outL2 = { topic: 'smart_traffic/demo/lane2/light', payload: lights[2] };
var outL3 = { topic: 'smart_traffic/demo/lane3/light', payload: lights[3] };
var outL4 = { topic: 'smart_traffic/demo/lane4/light', payload: lights[4] };
var outTiming = { topic: 'smart_traffic/demo/timing', payload: { remaining: state.remaining_sec, active_lane: state.active_lane } };

return [outFull, [outL1, outL2, outL3, outL4], outTiming];
